import{_ as o,o as a,c as s,ao as n}from"./chunks/framework.ucUddl5u.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":null}'),t={name:"guide/troubleshooting.md"};function r(i,e,h,d,l,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="Troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#Troubleshooting" aria-label="Permalink to &quot;Troubleshooting {#Troubleshooting}&quot;">​</a></h1><p>First move for any &quot;how do I&quot; or &quot;why is it doing that&quot; question: ask the agent in your session. Every workspace exports <code>$SOT_MANUAL</code>, pointing at the release checkout — this manual, the ADRs and the requirements — so the agent answers from the same docs you are reading, matched to the version you installed.</p><h2 id="window-does-not-open" tabindex="-1">The window does not open <a class="header-anchor" href="#window-does-not-open" aria-label="Permalink to &quot;The window does not open {#window-does-not-open}&quot;">​</a></h2><p>Run <code>sot-launch</code> in a terminal on the frontend machine: the window runs in the foreground there, so its error is printed. On Linux the window needs a desktop session (X11 or Wayland) and a working Vulkan driver.</p><ul><li><p><strong><code>no compatible wgpu adapter found</code></strong>: no usable Vulkan driver. Install the driver for your GPU (Mesa for Intel and AMD, the NVIDIA driver for NVIDIA); <code>vulkaninfo --summary</code>, from the <code>vulkan-tools</code> package, should then list the GPU.</p></li><li><p><strong>An error about opening a display</strong>: the shell has no graphical desktop, for example an SSH login. Run the window on the machine in front of you and keep the backend on the server; see <a href="./../start/remote">Going remote</a>.</p></li></ul><h2 id="The-connection-dropped" tabindex="-1">The connection dropped <a class="header-anchor" href="#The-connection-dropped" aria-label="Permalink to &quot;The connection dropped {#The-connection-dropped}&quot;">​</a></h2><p>Press <strong><code>F5</code></strong> to reconnect. The daemon replays what you missed or sends a fresh snapshot; agent sessions and the REPL keep running on the backend while you are away. See <a href="/ship-of-tools/dev/start/remote#Reconnecting">Going remote</a>.</p><h2 id="A-browser-page-says-127.0.0.1-refused-to-connect" tabindex="-1">A browser page says <code>127.0.0.1 refused to connect</code> <a class="header-anchor" href="#A-browser-page-says-127.0.0.1-refused-to-connect" aria-label="Permalink to &quot;A browser page says `127.0.0.1 refused to connect` {#A-browser-page-says-127.0.0.1-refused-to-connect}&quot;">​</a></h2><p><code>Shift+W</code> (built docs), <code>o</code> (video playback, Pluto) and <code>wglshow</code> pages are relayed through the frontend↔daemon connection, not through separate port forwards. Suspect that connection first: reconnect with <code>F5</code>, then reopen the page.</p><h2 id="The-Windows-taskbar-launch-looks-dead" tabindex="-1">The Windows taskbar launch looks dead <a class="header-anchor" href="#The-Windows-taskbar-launch-looks-dead" aria-label="Permalink to &quot;The Windows taskbar launch looks dead {#The-Windows-taskbar-launch-looks-dead}&quot;">​</a></h2><p>The Windows shortcut runs the launcher hidden, so an early failure can look like &quot;the taskbar click did nothing.&quot; Check these first:</p><ul><li><p><code>%LOCALAPPDATA%\\sot\\logs\\launch-status.txt</code> — last launcher phase or fatal status.</p></li><li><p><code>%LOCALAPPDATA%\\sot\\logs\\supervisor.log</code> — detailed launcher, rebuild, tunnel, and frontend respawn log.</p></li><li><p><code>%APPDATA%\\Microsoft\\Internet Explorer\\Quick Launch\\User Pinned\\TaskBar</code> — the pinned <code>.lnk</code>; stale pins can still point at an old binary or an old checkout.</p></li></ul><p>After changing the topology on the hub (a new <code>[host.&lt;name&gt;]</code>, a flag flip), <code>sotd topology sync</code> on every other box picks it up on its next launch — no shortcut re-run needed for that. Re-run the shortcut installer only after moving the repo or the launcher script:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pwsh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">scripts\\install-shortcut.ps1</span></span></code></pre></div><p>That refreshes the desktop shortcut and repoints any existing Ship of Tools taskbar pin to <code>scripts\\launch-sot.ps1</code>.</p><h2 id="A-session-will-not-start-on-a-shared-home" tabindex="-1">A session will not start on a shared home <a class="header-anchor" href="#A-session-will-not-start-on-a-shared-home" aria-label="Permalink to &quot;A session will not start on a shared home {#A-session-will-not-start-on-a-shared-home}&quot;">​</a></h2><p>The daemon keeps capsule session records under <code>${XDG_STATE_HOME:-~/.local/state}/sot</code> and refuses to start a capsule row on a remote filesystem (NFS, SMB/CIFS, 9p, an unqualified FUSE mount) or a volatile one (tmpfs, ramfs), answering <code>state_root_unqualified</code> and naming the filesystem. On a home shared over NFS, point each host&#39;s state root at its own local disk with a drop-in at <code>~/.config/systemd/user/sotd.service.d/state.conf</code>:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">XDG_STATE_HOME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/path/on/local/disk/state</span></span></code></pre></div><p>then <code>systemctl --user daemon-reload &amp;&amp; systemctl --user restart sotd</code>. Relocating the root does not migrate existing rows — end that host&#39;s capsule runs first. See <a href="./../concepts/sessions">Sessions and persistence</a>.</p><h2 id="Windows:-never-launch-the-daemon-from-an-agent&#39;s-shell" tabindex="-1">Windows: never launch the daemon from an agent&#39;s shell <a class="header-anchor" href="#Windows:-never-launch-the-daemon-from-an-agent&#39;s-shell" aria-label="Permalink to &quot;Windows: never launch the daemon from an agent&#39;s shell {#Windows:-never-launch-the-daemon-from-an-agent&#39;s-shell}&quot;">​</a></h2><p>Never start the frontend or the daemon from a shell running under an agent (a Claude pane, a capsule row&#39;s shell). The agent process sits in a Windows job object that forbids breakaway, and a daemon started there can never free the supervisors it spawns: its sessions die with it. Launch from the launcher or a plain shell. The daemon log says <code>this daemon&#39;s own job forbids breakaway</code> when this has happened.</p><h2 id="Enrolment-failures" tabindex="-1">Enrolment failures <a class="header-anchor" href="#Enrolment-failures" aria-label="Permalink to &quot;Enrolment failures {#Enrolment-failures}&quot;">​</a></h2><p>A host that should be reachable from every frontend but is not: see <a href="/ship-of-tools/dev/guide/enrolling#Reading-a-failure">Reading a failure</a> in the enrolment checklist.</p>',23)])])}const g=o(t,[["render",r]]);export{u as __pageData,g as default};
